"""Lightweight HTML summary reports for rtichoke."""
from __future__ import annotations
import json
from pathlib import Path
from typing import Dict, Union
import numpy as np
from rtichoke.calibration.calibration import _create_calibration_curve_list
from rtichoke.performance_data.performance_data import prepare_performance_data
from rtichoke.processing.plotly_helper_functions import _create_rtichoke_curve_list_binary

_CURVES=[("roc","ROC"),("lift","Lift"),("precision recall","Precision Recall"),("gains","Gains")]
def _spec(data,strat,curve,label):
 d=_create_rtichoke_curve_list_binary(performance_data=data,stratified_by=strat,curve=curve,size=500)
 return {"label":label,"title":f"{label} Curve","x_label":d["x_label"],"y_label":d["y_label"],"x_range":d["axes_ranges"]["xaxis"],"y_range":d["axes_ranges"]["yaxis"],"groups":d["reference_group_keys"],"colors":d["colors_dictionary"],"data":d["performance_data_ready_for_curve"].to_dicts(),"references":d["reference_data"].to_dicts()}
def _specs(data,strat): return [_spec(data,strat,c,l) for c,l in _CURVES]
def _calibration(probs,reals):
 d=_create_calibration_curve_list(probs,reals,size=550); colors={k:v[0] for k,v in d["colors_dictionary"].items()}
 return {"deciles":d["deciles_dat"].to_dicts(),"smooth":d["smooth_dat"].to_dicts(),"reference":d["reference_data"].to_dicts(),"histogram":d["histogram_for_calibration"].to_dicts(),"ranges":d["axes_ranges"],"colors":colors,"groups":[k for k in colors if k!="reference_line"]}
def _auc(y,p):
 y=np.asarray(y).ravel().astype(int);p=np.asarray(p).ravel().astype(float);pos=p[y==1];neg=p[y==0]
 return float("nan") if not len(pos) or not len(neg) else float(np.mean(pos[:,None]>neg[None,:])+.5*np.mean(pos[:,None]==neg[None,:]))
def _summaries(probs,reals):
 if isinstance(reals,dict) and probs.keys()==reals.keys(): return [{"Model":k,"Prevalence":float(np.mean(reals[k])),"AUC":_auc(reals[k],probs[k])} for k in probs]
 if not isinstance(reals,dict): return [{"Model":k,"Prevalence":float(np.mean(reals)),"AUC":_auc(reals,p)} for k,p in probs.items()]
 return []
def _table_data(data):
 cols=["reference_group","chosen_cutoff","ppcr","sensitivity","specificity","ppv","npv","lift","predicted_positives","net_benefit","true_positives","true_negatives","false_positives","false_negatives"]
 return [{k:r.get(k) for k in cols if k in r} for r in data.to_dicts()]
def _html(payload,sums):
 P=json.dumps(payload,separators=(",",":"),default=str).replace("</","<\\/");S=json.dumps(sums).replace("</","<\\/")
 return f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Summary Report</title><script src="https://cdn.jsdelivr.net/npm/d3@7/dist/d3.min.js"></script><style>
:root{{--ink:#2a3f5f;--muted:#6b7280;--blue:#337ab7;--rule:#e5e7eb;--soft:#f8fafc}}*{{box-sizing:border-box}}body{{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;color:#333;margin:0;background:#fff}}main{{max-width:1040px;margin:auto;padding:42px 34px 80px}}h1{{font-size:34px;font-weight:400;letter-spacing:-.5px;margin:0 0 30px}}h2{{font-size:26px;font-weight:400;margin:48px 0 15px;padding-top:4px}}h3{{font-size:18px;font-weight:400;margin:20px 0 6px;color:#444}}details{{border-top:1px solid var(--rule);border-bottom:1px solid var(--rule);padding:13px 0;margin-bottom:28px}}summary{{cursor:pointer;font-size:16px;color:#444}}.cheat{{line-height:1.85;padding:18px 2px 8px;color:#444}}table{{border-collapse:collapse;margin:12px 0 24px}}th,td{{border:1px solid #ddd;padding:8px 13px;text-align:center}}th{{font-weight:400}}.good{{background:#d9f2dc;font-weight:600}}.bad{{background:#f8d7da;font-weight:600}}.summary-table{{font-size:14px;min-width:300px}}.summary-table th{{background:#fafafa;color:#555}}.tabs{{display:flex;flex-wrap:wrap;border-bottom:1px solid #ddd;margin:8px 0 18px;gap:2px}}.tab{{border:0;background:none;padding:10px 15px 9px;border-bottom:3px solid transparent;cursor:pointer;font:inherit;font-size:14px;color:#666;transition:.15s}}.tab:hover{{color:#222;background:#fafafa}}.tab.active{{border-bottom-color:var(--blue);color:var(--blue)}}.subtabs{{margin-top:4px}}.panel{{display:none}}.panel.active{{display:block}}.chart{{max-width:650px;margin:12px auto 26px}}.title{{text-align:center;font-size:18px;color:#222;margin:8px 0 4px}}svg{{width:100%;height:auto;overflow:visible}}.axis text{{fill:var(--ink);font-size:12px}}.axis path,.axis line{{stroke:#c7ced8}}.grid line{{stroke:#e8edf2;stroke-opacity:.8}}.grid path{{stroke-width:0}}.line{{fill:none;stroke-width:2.2px}}.ref{{fill:none;stroke-width:1.4px;stroke-dasharray:4 4}}.axis-label{{fill:var(--ink);font-size:13px}}.legend{{display:flex;justify-content:center;gap:16px;flex-wrap:wrap;font-size:12px;margin:5px 0 3px}}.legend span{{display:inline-flex;align-items:center;gap:6px}}.legend i{{display:inline-block;width:22px;height:3px}}.tip{{position:fixed;pointer-events:none;padding:7px 10px;border-radius:3px;font-size:12px;opacity:0;color:#fff;z-index:20;box-shadow:0 2px 8px #0002}}.perf-wrap{{overflow:auto;max-height:620px;border:1px solid var(--rule);border-radius:3px}}.perf{{width:100%;margin:0;border:0;font-size:13px}}.perf th{{position:sticky;top:0;background:#fff;z-index:2;cursor:pointer;white-space:nowrap;color:#555;padding:10px 9px;border-bottom:1px solid #ccc}}.perf td{{padding:8px 9px}}.perf td,.perf th{{border-width:0 0 1px 0;border-color:#eee}}.perf tr.main:hover{{background:#f8fafc}}.perf .model{{text-align:left;font-weight:600}}.perf .metric{{min-width:78px;background-repeat:no-repeat;background-position:center;background-size:94% 76%}}.perf .expand{{width:30px;cursor:pointer;font-size:18px;color:#777}}.detail td{{text-align:left;background:#fafafa;padding:14px 18px}}.cm-title{{color:#555;margin-right:8px}}.cm{{display:inline-grid;grid-template-columns:auto auto;gap:3px;vertical-align:middle}}.cm span{{padding:5px 10px;border-radius:2px;min-width:72px;text-align:center}}.pos{{background:#d9f2dc}}.neg{{background:#f8d7da}}@media(max-width:700px){{main{{padding:24px 15px 55px}}h1{{font-size:29px}}h2{{font-size:23px}}.tab{{padding:9px 10px}}}}
</style></head><body><main><h1>Summary Report</h1><details><summary>Performance Metrics Cheat Sheet</summary><div class="cheat"><table><tr><th></th><th>Predicted Positive</th><th>Predicted Negative</th></tr><tr><th>Real Positive</th><td class="good">TP</td><td class="bad">FN</td></tr><tr><th>Real Negative</th><td class="bad">FP</td><td class="good">TN</td></tr></table><div><b>Prevalence</b> = (TP + FN) / N</div><div><b>PPCR (Predicted Positives Condition Rate)</b> = (TP + FP) / N</div><div><b>Sensitivity (Recall, True Positive Rate)</b> = TP / (TP + FN)</div><div><b>Specificity</b> = TN / (TN + FP)</div><div><b>PPV (Precision)</b> = TP / (TP + FP)</div><div><b>NPV</b> = TN / (TN + FN)</div><div><b>Lift</b> = PPV / Prevalence</div><div><b>Net Benefit</b> = TP/N - FP/N × p<sub>t</sub>/(1-p<sub>t</sub>)</div></div></details><div id="prev"></div>
<h2>Calibration</h2><div class="tabs"><button class="tab active" data-group="cal" data-target="smooth">Smooth</button><button class="tab" data-group="cal" data-target="discrete">Discrete</button></div><div id="smooth" class="panel active"><div id="smoothchart" class="chart"></div></div><div id="discrete" class="panel"><div id="discretechart" class="chart"></div></div>
<h2>Discrimination</h2><div id="auc"></div><div class="tabs"><button class="tab active" data-group="disc" data-target="thr">By Probability Threshold</button><button class="tab" data-group="disc" data-target="pcr">By Predicted Positives Condition Rate (PPCR)</button></div><div id="thr" class="panel active"><h3>Performance Metrics Curves</h3><div id="thrtabs" class="tabs subtabs"></div><div id="thrchart" class="chart"></div></div><div id="pcr" class="panel"><h3>Performance Metrics Curves</h3><div id="pcrtabs" class="tabs subtabs"></div><div id="pcrchart" class="chart"></div></div>
<h2>Utility (Decision Curve)</h2><div id="decision" class="chart"></div><h2>Performance Table</h2><div class="tabs"><button class="tab active" data-group="tbl" data-target="t1">By Probability Threshold</button><button class="tab" data-group="tbl" data-target="t2">By Predicted Positives Condition Rate (PPCR)</button></div><div id="t1" class="panel active"><div id="table-threshold"></div></div><div id="t2" class="panel"><div id="table-ppcr"></div></div></main><div class="tip"></div><script>
const R={P},SUM={S},tip=d3.select('.tip');function tbl(cols){{return `<table class="summary-table"><tr>${{cols.map(c=>`<th>${{c}}</th>`).join('')}}</tr>${{SUM.map(r=>`<tr>${{cols.map(c=>`<td>${{typeof r[c]==='number'?r[c].toFixed(3):r[c]}}</td>`).join('')}}</tr>`).join('')}}</table>`}}document.querySelector('#prev').innerHTML=tbl(['Model','Prevalence']);document.querySelector('#auc').innerHTML=tbl(['Model','AUC']);document.addEventListener('click',e=>{{if(!e.target.matches('button[data-target]'))return;let g=e.target.dataset.group,t=e.target.dataset.target;document.querySelectorAll(`button[data-group="${{g}}"]`).forEach(b=>b.classList.toggle('active',b===e.target));let ids=g==='cal'?['smooth','discrete']:g==='disc'?['thr','pcr']:['t1','t2'];ids.forEach(id=>document.getElementById(id).classList.toggle('active',id===t))}});
function legend(c,s){{let l=c.append('div').attr('class','legend');s.groups.forEach(g=>l.append('span').html(`<i style="background:${{s.colors[g]||'#333'}}"></i>${{g}}`))}}function draw(s,sel){{let c=d3.select(sel);c.selectAll('*').remove();c.append('div').attr('class','title').text(s.title);legend(c,s);let w=600,h=500,m={{top:20,right:28,bottom:68,left:76}},svg=c.append('svg').attr('viewBox',`0 0 ${{w}} ${{h}}`),x=d3.scaleLinear().domain(s.x_range).range([m.left,w-m.right]),y=d3.scaleLinear().domain(s.y_range).range([h-m.bottom,m.top]),ln=d3.line().defined(d=>Number.isFinite(+d.x)&&Number.isFinite(+d.y)).x(d=>x(+d.x)).y(d=>y(+d.y));svg.append('g').attr('class','grid').attr('transform',`translate(0,${{h-m.bottom}})`).call(d3.axisBottom(x).tickSize(-(h-m.top-m.bottom)).tickFormat(''));svg.append('g').attr('class','grid').attr('transform',`translate(${{m.left}},0)`).call(d3.axisLeft(y).tickSize(-(w-m.left-m.right)).tickFormat(''));svg.append('g').attr('class','axis').attr('transform',`translate(0,${{h-m.bottom}})`).call(d3.axisBottom(x));svg.append('g').attr('class','axis').attr('transform',`translate(${{m.left}},0)`).call(d3.axisLeft(y));svg.append('text').attr('class','axis-label').attr('x',(m.left+w-m.right)/2).attr('y',h-16).attr('text-anchor','middle').text(s.x_label);svg.append('text').attr('class','axis-label').attr('transform','rotate(-90)').attr('x',-(m.top+h-m.bottom)/2).attr('y',18).attr('text-anchor','middle').text(s.y_label);d3.group(s.references,d=>String(d.reference_group)).forEach((a,g)=>svg.append('path').datum(a).attr('class','ref').attr('stroke',s.colors[g]||'#999').attr('d',ln));s.groups.forEach(g=>{{let a=s.data.filter(d=>String(d.reference_group)===g);svg.append('path').datum(a).attr('class','line').attr('stroke',s.colors[g]||'#000').attr('d',ln)}});svg.append('rect').attr('x',m.left).attr('y',m.top).attr('width',w-m.left-m.right).attr('height',h-m.top-m.bottom).attr('fill','transparent').on('mousemove',ev=>{{let [mx,my]=d3.pointer(ev),n=null,z=1e99;s.data.forEach(d=>{{if(!Number.isFinite(+d.x)||!Number.isFinite(+d.y))return;let q=(x(+d.x)-mx)**2+(y(+d.y)-my)**2;if(q<z){{z=q;n=d}}}});if(n)tip.style('opacity',1).style('background',s.colors[String(n.reference_group)]||'#333').style('left',(ev.clientX+10)+'px').style('top',(ev.clientY+10)+'px').html(String(n.text||''))}}).on('mouseleave',()=>tip.style('opacity',0))}}
function ct(specs,nav,chart){{let n=d3.select(nav);specs.forEach((s,i)=>n.append('button').attr('class','tab'+(i?'':' active')).text(s.label).on('click',function(){{n.selectAll('.tab').classed('active',false);d3.select(this).classed('active',true);draw(s,chart)}}));draw(specs[0],chart)}}ct(R.threshold,'#thrtabs','#thrchart');ct(R.ppcr,'#pcrtabs','#pcrchart');draw(R.decision,'#decision');
function cal(type,sel){{let c=R.calibration,card=d3.select(sel);card.append('div').attr('class','title').text(type==='smooth'?'Calibration Curve — Smooth':'Calibration Curve — Discrete');let leg=card.append('div').attr('class','legend');c.groups.forEach(g=>leg.append('span').html(`<i style="background:${{c.colors[g]}}"></i>${{g}}`));let w=600,h=520,m={{top:20,right:25,bottom:105,left:76}},svg=card.append('svg').attr('viewBox',`0 0 ${{w}} ${{h}}`),x=d3.scaleLinear().domain(c.ranges.xaxis).range([m.left,w-m.right]),y=d3.scaleLinear().domain(c.ranges.yaxis).range([h-m.bottom,m.top]),ln=d3.line().defined(d=>Number.isFinite(+d.x)&&Number.isFinite(+d.y)).x(d=>x(+d.x)).y(d=>y(+d.y));svg.append('g').attr('class','grid').attr('transform',`translate(0,${{h-m.bottom}})`).call(d3.axisBottom(x).tickSize(-(h-m.top-m.bottom)).tickFormat(''));svg.append('g').attr('class','grid').attr('transform',`translate(${{m.left}},0)`).call(d3.axisLeft(y).tickSize(-(w-m.left-m.right)).tickFormat(''));svg.append('g').attr('class','axis').attr('transform',`translate(0,${{h-m.bottom}})`).call(d3.axisBottom(x));svg.append('g').attr('class','axis').attr('transform',`translate(${{m.left}},0)`).call(d3.axisLeft(y));svg.append('text').attr('class','axis-label').attr('x',(m.left+w-m.right)/2).attr('y',h-55).attr('text-anchor','middle').text('Predicted Probability');svg.append('text').attr('class','axis-label').attr('transform','rotate(-90)').attr('x',-(m.top+h-m.bottom)/2).attr('y',18).attr('text-anchor','middle').text('Observed Probability');svg.append('path').datum(c.reference).attr('class','ref').attr('stroke',c.colors.reference_line||'#888').attr('d',ln);let dat=type==='smooth'?c.smooth:c.deciles;c.groups.forEach(g=>{{let a=dat.filter(d=>String(d.reference_group)===g);svg.append('path').datum(a).attr('class','line').attr('stroke',c.colors[g]).attr('d',ln);if(type==='discrete')svg.selectAll(`.pt-${{g}}`).data(a).enter().append('circle').attr('cx',d=>x(+d.x)).attr('cy',d=>y(+d.y)).attr('r',4.5).attr('fill',c.colors[g]).attr('stroke','#fff').attr('stroke-width',1)}});let max=d3.max(c.histogram,d=>+d.counts)||1,hy=d3.scaleLinear().domain([0,max]).range([h-24,h-m.bottom+38]);c.histogram.forEach(d=>svg.append('rect').attr('x',x(+d.mids)-2).attr('width',4).attr('y',hy(+d.counts)).attr('height',h-24-hy(+d.counts)).attr('fill',c.colors[String(d.reference_group)]||'#777').attr('opacity',.35))}}cal('smooth','#smoothchart');cal('discrete','#discretechart');
const LABELS={{reference_group:'Model',chosen_cutoff:'Threshold',ppcr:'PPCR',sensitivity:'Sensitivity',specificity:'Specificity',ppv:'PPV',npv:'NPV',lift:'Lift',predicted_positives:'Predicted Positives',net_benefit:'Net Benefit'}};const METRICS=new Set(['sensitivity','specificity','ppv','npv']);function fmt(v){{return typeof v==='number'&&Number.isFinite(v)?v.toFixed(2):(v??'')}}function perfTable(rows,sel,isPPCR){{let keys=(isPPCR?['reference_group','ppcr']:['reference_group','chosen_cutoff']).concat(['sensitivity','specificity','ppv','npv','lift','predicted_positives','net_benefit']);let root=d3.select(sel),wrap=root.append('div').attr('class','perf-wrap'),table=wrap.append('table').attr('class','perf'),thead=table.append('thead').append('tr');thead.append('th').text('');keys.forEach(k=>thead.append('th').text(LABELS[k]||k).attr('title','Click to sort').on('click',()=>{{rows.sort((a,b)=>d3.ascending(a[k],b[k]));render()}}));let body=table.append('tbody');function render(){{body.selectAll('*').remove();rows.forEach(r=>{{let tr=body.append('tr').attr('class','main'),ex=tr.append('td').attr('class','expand').text('›');keys.forEach(k=>{{let td=tr.append('td').attr('class',(k==='reference_group'?'model ':'')+(METRICS.has(k)?'metric':''));if(METRICS.has(k)&&Number.isFinite(+r[k]))td.style('background-image',`linear-gradient(90deg, #d9f2dc ${{Math.max(0,Math.min(100,+r[k]*100))}}%, transparent 0)`);td.text(fmt(r[k]))}});let det=body.append('tr').attr('class','detail').style('display','none'),cell=det.append('td').attr('colspan',keys.length+1);cell.html(`<span class="cm-title">Confusion Matrix</span><span class="cm"><span class="pos">TP ${{fmt(r.true_positives)}}</span><span class="neg">FN ${{fmt(r.false_negatives)}}</span><span class="neg">FP ${{fmt(r.false_positives)}}</span><span class="pos">TN ${{fmt(r.true_negatives)}}</span></span>`);ex.on('click',()=>{{let open=det.style('display')!=='none';det.style('display',open?'none':'table-row');ex.text(open?'›':'⌄')}})}})}}render()}}perfTable(R.tables.threshold,'#table-threshold',false);perfTable(R.tables.ppcr,'#table-ppcr',true);
</script></body></html>'''
def create_summary_report(probs:Dict[str,np.ndarray],reals:Union[np.ndarray,Dict[str,np.ndarray]],output_file:str|Path="summary_report.html",by:float=.01)->Path:
 threshold=prepare_performance_data(probs=probs,reals=reals,stratified_by=("probability_threshold",),by=by);ppcr=prepare_performance_data(probs=probs,reals=reals,stratified_by=("ppcr",),by=by);payload={"threshold":_specs(threshold,"probability_threshold"),"ppcr":_specs(ppcr,"ppcr"),"decision":_spec(threshold,"probability_threshold","decision","Decision"),"calibration":_calibration(probs,reals),"tables":{"threshold":_table_data(threshold),"ppcr":_table_data(ppcr)}};out=Path(output_file);out.write_text(_html(payload,_summaries(probs,reals)),encoding="utf-8");return out
